content:
&emsp;&emsp;領導又給我安排任務：要求部署腳本里能夠對服務器信息做一些基本的檢查，比如 CPU 得多少核心，內存 得多少 G，磁盤得多大等等，不錯檢查得多詳細，至少能滿足部署基本的要求（我覺得他可能知道我最近學 go）。打工人，牛馬魂，冩就冩！
&emsp;&emsp;冩之前還是要先想一下怎麼冩的：


檢查項肯定是結構體，包含一些基本字段；
需要有參數解析，區分單機還是多機，多級情況服務器情況可以適量減少；另外還需要 端口，用來檢測服務端口是否有佔用；
檢查的結果需要格式化輸出


main
定義一些常量作為服務器的基本要求；
flag 用於定義需要的參數；
checkItem 就是檢查項，每個檢查項都有對應的方法，但返回的結構是統一的；用於定義需要的參數；
checkItemList 是所有檢查項的集合，一開始想用切片的，比較容易拓展，後來想想檢查的內容是固定的，就直接用數組了；
checkByGoTable 和 checkByGoPretty 是分別用 兩個庫 輸出的表格

// 服務器部署配置要求const (	ExpBash  = &quot;bash&quot;	ExpCPU   = 4	ExpMem   = 32	ExpDisk  = 200	ExpNFS   = &quot;x.x.x.x:/x&quot;	ScanPort = &quot;&quot;)// 檢查項type CheckItem struct &#123;	name, expect, current, status, advice string&#125;var (	mode  string	host  string	ports string)func main() &#123;	// 參數解析	flag.StringVar(&amp;mode, &quot;m&quot;, &quot;standalone&quot;, &quot;standalone 單機 \t multi 多機&quot;)	flag.StringVar(&amp;host, &quot;h&quot;, &quot;127.0.0.1&quot;, &quot;待掃描主機&quot;)	flag.StringVar(&amp;ports, &quot;p&quot;, &quot;&quot;, &quot;待掃描端口&quot;)	flag.Parse()	// 進行基本檢查	checkItemList := [6]CheckItem&#123;checkBash(), checkCPU(), checkMem(), checkDisk(), checkPort(host, ports)&#125;	// 多機檢查 nfs 掛載	if mode != &quot;standalone&quot; &#123;		checkItemList[5] = checkMount()	&#125;	checkByGotable(&amp;checkItemList)	checkByGoPretty(&amp;checkItemList)&#125;

gotablefunc checkByGoTable(checkItemList *[6]CheckItem) &#123;	// 繪製表格	checkTable, _ := gotable.Create(&quot;檢查序號&quot;, &quot;檢查內容&quot;, &quot;預期情況&quot;, &quot;當前結果&quot;, &quot;檢查狀態&quot;, &quot;檢查建議&quot;)	// 設置左對齊	for _, c := range checkTable.GetColumns() &#123;		checkTable.Align(c, gotable.Left)	&#125;	// 添加數據	for i, ci := range checkItemList &#123;		if ci == (CheckItem&#123;&#125;) &#123;			break		&#125;		checkTable.AddRow([]string&#123;strconv.Itoa(i + 1), ci.name, ci.expect, ci.current, ci.status, ci.advice&#125;)	&#125;	fmt.Println(checkTable)&#125;

go-prettyfunc checkByGoPretty(checkItemList *[6]CheckItem) &#123;	// 繪製表格	t := table.NewWriter()	t.SetOutputMirror(os.Stdout)	// t.SetTitle(&quot;Check Result&quot;)	// t.SetStyle(table.StyleColoredBright)	// 表頭	header := table.Row&#123;&quot;檢查內容&quot;, &quot;預期情況&quot;, &quot;當前結果&quot;, &quot;檢查狀態&quot;, &quot;檢查建議&quot;&#125;	t.AppendHeader(header)	// 自動索引	t.SetAutoIndex(true)	//添加數據	for _, ci := range checkItemList &#123;		if ci == (CheckItem&#123;&#125;) &#123;			break		&#125;		t.AppendRow(table.Row&#123;ci.name, ci.expect, ci.current, ci.status, ci.advice&#125;)	&#125;	t.Render()&#125;

&emsp;&emsp;比較一下兩個庫繪製表格的代碼，由此可以歸納出此類庫的使用方法大致差不多：創建表格對象——添加表頭——添加數據，其他就是表格的額外配置或者個性化處理，比如 column 居中。 gotable 比較簡單，一開始用它也是處於這個原因。而相對而言 go-pretty 的功能就比較強大，可以更好得個性化配置表格。對於這個簡單的要求，本來用 gotable 就已經滿足了，為什麼後來又轉用 go-pretty呢？先來看張圖！

color&emsp;&emsp;注意看第一張由 gotable 繪製的表格紅框框出的部分，它 不！對！齊！ 這簡直是要逼死強迫症啊！再細看一下，咦？表格裡第一行檢查 Bash 環境是對齊的，與其他唯一的不同是……顏色輸？！
&emsp;&emsp;是的，不如我的所料的確如此！原因是我在優化的代碼時候，發現表格格式化輸出固然已經不錯，但是如果想更加醒目地展現檢查的結果，會不會加點顏色會更好呢？於是調整如下代碼（節選）：
字符串if strings.Contains(osBash, ci.expect) &#123;	ci.status = &quot;PASS&quot;&#125; else &#123;	ci.status = &quot;NOT PASS&quot;	ci.advice = &quot;服務器 bash 環境異常，請調整為 bash !&quot;&#125;

color 包if logicalCoreCount &lt; expectCoreCount || totalCPUPercent[0] &gt; 80.00 &#123;	ci.status = color.RedString(&quot;NOT PASS&quot;)	ci.advice = color.RedString(fmt.Sprintf(&quot;服務器 CPU 核數不夠或使用率過高，當前使用率為 %.2f%% ，請調整 CPU 配置!&quot;, totalCPUPercent[0]))&#125; else &#123;	ci.status = color.GreenString(&quot;PASS&quot;)&#125;

go-pretty 包	if space[len(space)-1] &lt; ExpDisk &#123;		ci.status = redText(&quot;NOT PASS&quot;)		ci.advice = redText(&quot;服務器當前最大磁盤空間不夠，請擴容磁盤!&quot;)	&#125; else &#123;		ci.status = greenText(&quot;PASS&quot;)	&#125;//  封裝了一下調整文本顏色的方法func redText(str string) string &#123;	return text.Colors&#123;text.FgRed&#125;.Sprintf(&quot;%s&quot;, str)&#125;func greenText(str string) string &#123;	return text.Colors&#123;text.FgGreen&#125;.Sprintf(&quot;%s&quot;, str)&#125;


&emsp;&emsp;現在結合代碼和截圖就容易看出：如果只用 字符串，gotable 是完全沒有問題的；而用其他方式，儘管字段的數據類型仍然是 string，它就不兼容了。發現這個問題後，我才想用 go-pretty 去更好地輸出表格。

&emsp;&emsp;以前部署公司服務的時候，經常會打開 swagger 頁面：一來是可以驗證服務正常，相當於 1 次手動的就緒探針；二來，有些簡單接口直接就可以在頁面上做調試，不用再打開 postman 或者 apifox，當時覺得這東西真不錯。
&emsp;&emsp;第一步自然是面向互聯網。跟著網上的教程基本上就能搞個七七八八，我這裡就是記錄一下。
初始化go install github.com/swaggo/swag/cmd/swag@latestgo get -u -v github.com/swaggo/gin-swaggergo get -u -v github.com/swaggo/filesswag init

&emsp;&emsp;以上都是很常規的操作——用什麼庫就先安裝什麼庫。不過我一般的做法是直接在代碼裡貼上使用的庫，然後 go mod tidy 一下就好了。需要注意的 swag init 這一步，它會在當前目錄下創建 docs 文件夾，並且自動創建 docs.go、swagger.json 和 swagger.yaml 三個文件，至於裡面是什麼，我不建議現在去看，等待會我們填上代碼再看也不遲。
swagger 基本信息註解設置// @title MyGin API// @version 1.0// @description A Gin Project By Myself// @BasePath /api/v1// #Host 192.168.10.11:9000// @schemes http httpsfunc main() &#123;  .....&#125;

代碼設置func RegisterSwagger(r *gin.Engine) &#123;	docs.SwaggerInfo.BasePath = &quot;/api/v1&quot;	docs.SwaggerInfo.Title = &quot;MyGin API&quot;	docs.SwaggerInfo.Description = &quot;A Gin Project By Myself&quot;	docs.SwaggerInfo.Host = fmt.Sprintf(&quot;192.168.10.11:9000&quot;)	docs.SwaggerInfo.Version = &quot;1.0&quot;	docs.SwaggerInfo.Schemes = []string&#123;&quot;http&quot;, &quot;https&quot;&#125;	r.GET(&quot;/swagger/*any&quot;, ginSwagger.WrapHandler(swaggerFiles.Handler))&#125;

&emsp;&emsp;可以通過 註解 和 字段賦值 兩種方式配置 swagger 頁面的一些基本信息，項目啟動後 訪問 http://ip:port/swagger/index.html即可。

&emsp;&emsp;有好奇寶寶肯定要問了：如果同時使用 2 種設置方式，那麼以哪一個為準呢？直接試試就知道了：註解不變，修改一下代碼：
func RegisterSwagger(r *gin.Engine) &#123;	docs.SwaggerInfo.BasePath = &quot;/api&quot;	docs.SwaggerInfo.Title = &quot;MyGin&quot;	docs.SwaggerInfo.Description = &quot;A Simple Gin Project&quot;	docs.SwaggerInfo.Host = fmt.Sprintf(&quot;192.168.10.11:9000&quot;)	r.GET(&quot;/swagger/*any&quot;, ginSwagger.WrapHandler(swaggerFiles.Handler))&#125;


&emsp;&emsp;對比一下 2 張圖，可以發現：**最終的顯示效果是以代碼裡字段賦值的方式為準，如果有些字段沒有賦值，就仍顯示 註解 的內容。**
swagger 接口信息&emsp;&emsp;剛才只是 swagger 頁面的基本信息，更為重要的其實是 接口信息，我們只需要在對應的接口上添加註解就行了。
// @Summary Ping// @Description 測試連通性// @Tags 測試參數臨時接口// @Produce json// @Success 200	&#123;object&#125; response.Result// @Router /example/ping [get]func HelloPing(c *gin.Context) &#123;	response.Success(c, &quot;ping&quot;)&#125;// @Summary Hello By Form// @Description 測試表單參數// @Tags 測試參數臨時接口// @Accept multipart/form-data// @Produce json// @Param name formData string true &quot;Name&quot;// @Param age formData int true &quot;Age&quot;// @Router /example/helloform [post]func HelloForm(c *gin.Context) &#123;	name := c.PostForm(&quot;name&quot;)	age := c.PostForm(&quot;age&quot;)	response.Success(c, fmt.Sprintf(&quot;Hello guy ! Your name is [%s], age is [%s]&quot;, name, age))&#125;

&emsp;&emsp;這兩個例子雖然簡單，但其實真的要細講也要費一些篇幅，我建議是依葫蘆畫瓢自己多試試——因為我自己都是根據網頁上的教程試了半天，才稍微有些理解。


&emsp;&emsp;比如說：我在 ping 接口加了一條 // @Success 200	&#123;object&#125; response.Result 的註解，所以 swagger 頁面上 ping 接口就多了 Responses 200 的內容，而這個 response.Result 是我自定義的結構體，
type Result struct &#123;	Code int         `json:&quot;code&quot;`           // 狀態碼	Msg  string      `json:&quot;msg&quot;`            // 提示信息	Data interface&#123;&#125; `json:&quot;data,omitempty&quot;` // 返回數據（可選）&#125;

&emsp;&emsp;又比如說，我在 helloform 接口加了兩條 // @Param name formData string true &quot;Name&quot; // @Param age formData int true &quot;Age&quot;，因此 swagger 頁面上就出現了該接口需要的參數和數據類型。
&emsp;&emsp;看起來好像也沒有什麼，為什麼說清楚不容易呢？因為涉及到的東西比較多：如果不用 formData 是 path 又或者是 url 又或者是 json，那麼填的東西也不一樣。所以還是建議根據官方文檔一一去嘗試，用得多自然就知道。考慮到 json 最為常用，這邊再說下這個。
// @Summary 用戶查詢// @Description 用戶查詢接口// @Tags 用戶管理// @Accept json// @Produce json// @Param User body request.UserListRequest true &quot;用戶查詢信息&quot;// @Router /user/list [post]func UserList(c *gin.Context) &#123;  ......&#125;type PageRequest struct &#123;	Page     int `json:&quot;page&quot; binding:&quot;gte=1&quot; example:&quot;1&quot;`	PageSize int `json:&quot;page_size&quot; binding:&quot;gte=1,lte=100&quot; example:&quot;10&quot;`&#125;type UserListRequest struct &#123;	// 通過 binding 標籤做基礎參數校驗	// keyword 用於模糊搜索用戶名	// min_age / max_age 控制年齡篩選範圍	PageRequest	Keyword string `json:&quot;keyword&quot; example:&quot;&quot;`                                // 可選關鍵詞（模糊搜索）	MinAge  int    `json:&quot;min_age&quot; binding:&quot;omitempty,gte=18&quot; example:&quot;20&quot;`   // 最小年齡（可選）	MaxAge  int    `json:&quot;max_age&quot; binding:&quot;omitempty,lte=120&quot; example:&quot;100&quot;` // 最大年齡（可選）&#125;

&emsp;&emsp;可以看到，這裡的 Param 冩了自己定義的 UserListRequest 結構體；同時在結構體裡，這樣 swagger 頁面上就有了相應字段；再用 example 標籤，既能提示數據類型，又能給使用人提供例子，最後的效果如圖顯示。

&emsp;&emsp;最後貼一張目前冩的接口的大合照——一家人最重要就是整整齊齊！

回到開頭&emsp;&emsp;還記得該開始說的 swag init 和自動創建的文件嗎？其實，只要給代碼加上註解，都需要執行 swag init。考慮到文件裡的內容太多，就直接截取部分，可以自己看下文件裡的內容是不是和頁面上看到的一致（json 和 yaml 文件裡關於 swagger 的內容是一致的，只是展現形式不一樣）



困擾我的問題&emsp;&emsp;最近冩 swagger 的時候，有一個問題困擾了我好久，就是 BasePath。我的路由代碼是這樣的：
v1 := r.Group(&quot;/api/v1&quot;)&#123;	exampleRouter := v1.Group(&quot;/example&quot;)	ExampleRouter(exampleRouter)	userRouter := v1.Group(&quot;/user&quot;)	UserRouter(userRouter)&#125;

&emsp;&emsp;接口訪問的路徑是 /api/v1/user/xxxx，於是註解自然而然就這麼冩了：
// @Param User body request.LoginRequest true &quot;用戶登錄信息&quot;// @Router /api/v1/user/login [post]func Login(c *gin.Context) &#123;&#125;

&emsp;&emsp;這樣的話，swagger 頁面顯示的也是 /api/v1/user/login

&emsp;&emsp;然後問題就來了，通過頁面請求發現地址變成了 /api/v1/api/v1/user/login

&emsp;&emsp;後來我才理解 BasePath 就是會在頁面看到路徑前面自動拼接的路徑：如果完整路徑是 /api/v1/user/login，那麼註解裡就不用再重複冩 /api/v1/。不然，把 BasePath 冩成 /，也 OK，只要清楚真正的路徑是什麼就行。

&emsp;&emsp;萬萬沒想到這東西居然還有第三回！但是，第三回又是必然的——之前的表格都是終端輸出的，如果有朝一日需要冩入到 Excel 表格裡呢？
&emsp;&emsp;這就需要使用 excelize 這個庫了。考慮到檢查項的代碼比較簡單，使用場景也有限，我們用之前使用 client-go 獲取資源的代碼來實驗（實驗的時候當然也對代碼進行了新的優化）。
整體代碼創建表格f := excelize.NewFile()fXlsxName := &quot;TPT-SAAS-Resources.xlsx&quot;fSheetName := &quot;resources&quot;f.NewSheet(fSheetName)f.DeleteSheet(&quot;Sheet1&quot;)// 表頭headers := [...]string&#123;&quot;Namespace&quot;, &quot;App&quot;, &quot;Replicas&quot;, &quot;Resource&quot;, &quot;Requests&quot;, &quot;Limits&quot;&#125;for col, header := range headers &#123;	axis, _ := excelize.CoordinatesToCellName(col+1, 1)	f.SetCellValue(fSheetName, axis, header)&#125;

&emsp;&emsp;看起來很簡單的表格實例，需要注意的主要是 sheet 頁：後續的操作都是基於 sheet 頁的，默認 sheet 頁就是 Sheet1，這裡我自定義了 sheet 頁並刪除默認的，如果不需要直接也可以。
添加數據rowNum := 2config, _ := clientcmd.BuildConfigFromFlags(&quot;&quot;, kc)clientset, _ := kubernetes.NewForConfig(config)deployClient := clientset.AppsV1().Deployments(ns)deployList, err := deployClient.List(context.TODO(), metav1.ListOptions&#123;&#125;)CheckErr(err)for _, deploy := range deployList.Items &#123;	appResources := deploy.Spec.Template.Spec.Containers[0].Resources	RequestsResource := appResources.Requests	limitResource := appResources.Limits	f.SetCellValue(fSheetName, fmt.Sprintf(&quot;A%d&quot;, rowNum), deploy.ObjectMeta.Namespace)	f.SetCellValue(fSheetName, fmt.Sprintf(&quot;B%d&quot;, rowNum), deploy.ObjectMeta.Name)	f.SetCellValue(fSheetName, fmt.Sprintf(&quot;C%d&quot;, rowNum), *deploy.Spec.Replicas)	f.SetCellValue(fSheetName, fmt.Sprintf(&quot;D%d&quot;, rowNum), &quot;CPU&quot;)	f.SetCellValue(fSheetName, fmt.Sprintf(&quot;E%d&quot;, rowNum), RequestsResource.Cpu())	f.SetCellValue(fSheetName, fmt.Sprintf(&quot;F%d&quot;, rowNum), limitResource.Cpu())	// 合併單元格	oldRow := rowNum	rowNum++	newRow := rowNum	f.MergeCell(fSheetName, fmt.Sprintf(&quot;A%d&quot;, oldRow), fmt.Sprintf(&quot;A%d&quot;, newRow))	f.MergeCell(fSheetName, fmt.Sprintf(&quot;B%d&quot;, oldRow), fmt.Sprintf(&quot;B%d&quot;, newRow))	f.MergeCell(fSheetName, fmt.Sprintf(&quot;C%d&quot;, oldRow), fmt.Sprintf(&quot;C%d&quot;, newRow))	f.SetCellValue(fSheetName, fmt.Sprintf(&quot;D%d&quot;, rowNum), &quot;Mem&quot;)	f.SetCellValue(fSheetName, fmt.Sprintf(&quot;E%d&quot;, rowNum), RequestsResource.Memory())	f.SetCellValue(fSheetName, fmt.Sprintf(&quot;F%d&quot;, rowNum), limitResource.Memory())	rowNum++&#125;

&emsp;&emsp;這裡的添加數據其實有些複雜了，其實可以使用流式冩入來更高效的完成（可以簡單理解為按行冩入）。複雜的原因，主要是我想對一些單元格進行合併，才會有上面的 oldRow 和 newRow，而 rowNum 是從 2 算起的（第一行是表頭），這樣對能對 A2A3、B2B3、A4A5、B4B5 這樣的單元格進行合併。
保存文件if err := f.SaveAs(fXlsxName); err != nil &#123;	fmt.Println(err)&#125;fmt.Printf(&quot;保存 %s 成功！\n&quot;, fXlsxName)

&emsp;&emsp;數據添加後自然需要保存一下才能看到。
查看效果
&emsp;&emsp;可以看到單元格已經合併了，不過沒有居中。實際上代碼也可以完成居中，個人覺得代碼裡通過操作單元格的方式實現居中比較麻煩，不如在 office 軟件裡操作地更快。而合併單元就算通過 office 也要一個個選中才能合併，又不如通過程序來得方便了。

&emsp;從內容上講其實這篇文章的內容已經結束了，但別忘了之前我們還冩了終端表格，如果需要同時實現兩者，除了引入新的標誌和參數，還要對代碼進行拆分。

拆分代碼func setXlsxFile() &#123;	rsXlsx.NewSheet(sheetName)	rsXlsx.DeleteSheet(&quot;Sheet1&quot;)	headers := [...]string&#123;&quot;Kind&quot;, &quot;App&quot;, &quot;Resource&quot;, &quot;Requests&quot;, &quot;Limits&quot;&#125;	for col, header := range headers &#123;		axis, _ := excelize.CoordinatesToCellName(col+1, 1)		rsXlsx.SetCellValue(sheetName, axis, header)	&#125;&#125;func setConsoleTable() &#123;	rsTable.SetOutputMirror(os.Stdout)	header := table.Row&#123;&quot;Kind&quot;, &quot;App&quot;, &quot;Resources&quot;, &quot;Requests&quot;, &quot;Limits&quot;&#125;	rsTable.AppendHeader(header)	rsTable.SetColumnConfigs([]table.ColumnConfig&#123;		&#123;Number: 1, AutoMerge: true, Align: text.AlignRight, VAlign: text.VAlignMiddle&#125;,		&#123;Number: 2, AutoMerge: true, Align: text.AlignLeft, VAlign: text.VAlignMiddle&#125;,	&#125;)&#125;

&emsp;&emsp;兩個函數，兩種表格，兩種表頭設置方式。
type ControllerResources struct &#123;	Kind      string	Name      string	Resources corev1.ResourceRequirements&#125;func addResourceToTable(cr *ControllerResources) &#123;	rsTable.AppendRow(table.Row&#123;cr.Kind, cr.Name, &quot;cpu&quot;, cr.Resources.Requests.Cpu(), cr.Resources.Limits.Cpu()&#125;, rowConfigAutoMerge)	rsTable.AppendRow(table.Row&#123;cr.Kind, cr.Name, &quot;memory&quot;, cr.Resources.Requests.Memory(), cr.Resources.Limits.Memory()&#125;, rowConfigAutoMerge)	rsTable.AppendSeparator()&#125;func addResourceToXlsx(cr *ControllerResources) &#123;	// 如果不合並單元，可以考慮流式冩入	rsXlsx.SetCellValue(sheetName, fmt.Sprintf(&quot;A%d&quot;, rowNum), cr.Kind)	rsXlsx.SetCellValue(sheetName, fmt.Sprintf(&quot;B%d&quot;, rowNum), cr.Name)	rsXlsx.SetCellValue(sheetName, fmt.Sprintf(&quot;C%d&quot;, rowNum), &quot;CPU&quot;)	rsXlsx.SetCellValue(sheetName, fmt.Sprintf(&quot;D%d&quot;, rowNum), cr.Resources.Requests.Cpu())	rsXlsx.SetCellValue(sheetName, fmt.Sprintf(&quot;E%d&quot;, rowNum), cr.Resources.Limits.Cpu())	// 合併單元格	oldRow := rowNum	rowNum++	newRow := rowNum	rsXlsx.MergeCell(sheetName, fmt.Sprintf(&quot;A%d&quot;, oldRow), fmt.Sprintf(&quot;A%d&quot;, newRow))	rsXlsx.MergeCell(sheetName, fmt.Sprintf(&quot;B%d&quot;, oldRow), fmt.Sprintf(&quot;B%d&quot;, newRow))	rsXlsx.SetCellValue(sheetName, fmt.Sprintf(&quot;C%d&quot;, rowNum), &quot;Mem&quot;)	rsXlsx.SetCellValue(sheetName, fmt.Sprintf(&quot;D%d&quot;, rowNum), cr.Resources.Requests.Memory())	rsXlsx.SetCellValue(sheetName, fmt.Sprintf(&quot;E%d&quot;, rowNum), cr.Resources.Limits.Memory())	rowNum++&#125;

&emsp;&emsp;不同表格，不同的添加數據方式。函數的參數是自定義結構體，這樣添加參數的時候，不用從數據結構上考慮是 Deployment 還是 StatefulSet。
func init() &#123;	rootCmd.AddCommand(rsCmd)	rsCmd.AddCommand(dpCmd)	rsCmd.AddCommand(sfsCmd)	rsCmd.PersistentFlags().StringVarP(&amp;output, &quot;output&quot;, &quot;o&quot;, &quot;console&quot;, &quot;output format(console/file)&quot;)	switch output &#123;	case &quot;console&quot;:		setConsoleTable()		usedFunc = addResourceToTable	case &quot;file&quot;:		setXlsxFile()		usedFunc = addResourceToXlsx	default:		panic(&quot;Output must be one of file or console!&quot;)	&#125;&#125;

&emsp;&emsp;output 就是新加的標識，dp和 sts 子命令都需要，因此通過 rsCmd.PersistentFlags().StringVarP(&amp;output, &quot;output&quot;, &quot;o&quot;, &quot;console&quot;, &quot;output format(console/file)&quot;)添加到 rs 的父命令中，並且把函數當作變量，通過參數賦值；
func saveTable() &#123;	switch output &#123;	case &quot;console&quot;:		rsTable.Render()	case &quot;file&quot;:		if err := rsXlsx.SaveAs(xlsxName); err != nil &#123;			fmt.Println(err)		&#125;		fmt.Printf(&quot;保存 %s 成功！\n&quot;, xlsxName)	&#125;&#125;

&emsp;&emsp;根據參數輸出不同的表格；
var dpCmd = &amp;cobra.Command&#123;	Use:   &quot;dp&quot;,	Short: &quot;get resources of deployment&quot;,	Long:  &quot;A cli to get resources of deployment by client-go and cobra&quot;,	// 使用 dp 子命令可以指定 deploy 名稱，否則輸出所有	Example: &quot; mykube rs dp \n mykube rs dp -a &lt;deploy_name&gt;&quot;,	Run: func(cmd *cobra.Command, args []string) &#123;		config, _ := clientcmd.BuildConfigFromFlags(&quot;&quot;, kc)		clientset, _ := kubernetes.NewForConfig(config)		dpClient := clientset.AppsV1().Deployments(ns)		if len(app) == 0 || app == &quot;all&quot; &#123;			dpList, _ := dpClient.List(context.TODO(), metav1.ListOptions&#123;&#125;)			for _, dp := range dpList.Items &#123;				usedFunc(&amp;ControllerResources&#123;&quot;Deployment&quot;,					dp.Name,					dp.Spec.Template.Spec.Containers[0].Resources&#125;,				)			&#125;		&#125; else &#123;			dp, _ := dpClient.Get(context.TODO(), app, metav1.GetOptions&#123;&#125;)			usedFunc(&amp;ControllerResources&#123;&quot;Deployment&quot;,				dp.Name,				dp.Spec.Template.Spec.Containers[0].Resources&#125;,			)		&#125;		saveTable()	&#125;,&#125;

&emsp;&emsp;上次以 Statefulset 的代碼為例，這次就拿 Deployment ，到這裡就基本一樣，sfsCmd 的命令裡就把變量換一換就行。

小結一下&emsp;&emsp;一開始只是想記錄一下一些庫的使用方法，沒想到用著用著還給優化上了，可見代碼並不是一成不變，會跟著需求和想法而動。&emsp;&emsp;什麼，你問我現在還有沒有優化空間？&emsp;&emsp;有啊：比如 dpCmd 和 sfsCmd 兩個子命令的代碼就高度相似，邏輯完全一樣。老實說我想用泛型或者反射處理一下的，就把代碼扔給 AI，結果本地調試了老半天不得行，不然這期內容昨天就能發出來。

&emsp;&emsp;入職沒多久，都還沒有熟悉公司運維的各個環境呢，就接到領導安排的開發任務：畢竟面試時候也問過相關的問題，比如常用編程語言等，估計也是想借此看下我的實際水平。恰好，需求的內容也是之前沒有接觸過的領域，我也能通過這次編程學到新的內容。
先思後行&emsp;&emsp;一陣簡單的需求分析之後，基本的操作流程如下：

創建機器人
獲取消息文件
sql 簡單校驗
數據庫執行
回覆輸出消息

創建機器人
&emsp;這一步其實沒啥特別要說的，根據網上的教程，Telegram 添加 @BotFather 的官方賬號，發個 /start 的消息再按照一步步提示就行，最為重要的是獲取機器人的 token，當然如果剛開始沒記錄後面再執行相關命令也可以重新獲取

Golang 版
&emsp;由於之前用 goland 比較多，即使冩的都是些簡單的程序但也算熟悉，加上坐我右邊的同事也是用 go 實現其他機器人的功能，理所當然選擇它。根據 Bot API Library Examples 列出的，比較幾個包之後，選擇 TG - Telegram Bot Framework for Go。選擇的理由很簡單——給出的 ReadMe 足夠多！本地運行 example 代碼，再配合 TG 機器人的返回消息，就大概清楚需要調用哪些 API：針對文件的話，主要的程序都在以下代碼塊內完成：

b.On.Message.Document(func(ctx *ctx.Context) error &#123;    ……    ……    ……)&#125;

獲取消息文件
&emsp;&emsp;實際程序的第一步又可以簡單分為 3 個過程：

對消息的文件進行後綴名檢查// 文件消息sqlFileMsg := ctx.EffectiveMessage.Document// 判斷消息是否包含文件if sqlFileMsg == nil &#123;    return ctx.Reply(&quot;請確實文件消息是否存在！&quot;).Send().Err()&#125;// 檢查 SQL 文件後綴名msgFileName := sqlFileMsg.FileNameif !strings.HasSuffix(msgFileName, &quot;sql&quot;) &#123;    return ctx.Reply(&quot;SQL 文件必須以 .sql 為後綴名！&quot;).Send().Err()&#125;

根據 fileID 獲取文件實際鏈接const (    // bot botToken    botToken = &quot;xxxxxxxxxxxxxxx&quot;    // API 基礎 URL    apiBase = &quot;https://api.telegram.org/bot&quot; + botToken    // 文件下載 基礎 URL    fileBase = &quot;https://api.telegram.org/file/bot&quot; + botToken)// 定義文件請求響應體type GetFileResp struct &#123;    Ok     bool `json:&quot;ok&quot;`    Result struct &#123;        FileID   string `json:&quot;file_id&quot;`        FileSize int    `json:&quot;file_size&quot;`        FilePath string `json:&quot;file_path&quot;`    &#125; `json:&quot;result&quot;`&#125;// 調用 getFile 接口 根據 fileID 獲取 filePathfunc getTgFilePathByFileID(fileID string) (string, error) &#123;    url := fmt.Sprintf(&quot;%s/getFile?file_id=%s&quot;, apiBase, fileID)    resp, err := http.Get(url)    if err != nil &#123;        return &quot;&quot;, err    &#125;    defer resp.Body.Close()    if resp.StatusCode != http.StatusOK &#123;        panic(fmt.Sprintf(&quot;獲取文件失敗, 狀態碼為：%d&quot;, resp.StatusCode))    &#125;    var getFileResp GetFileResp    if err := json.NewDecoder(resp.Body).Decode(&amp;getFileResp); err != nil &#123;        panic(err)    &#125;    if !getFileResp.Ok &#123;        panic(&quot;Telegram API 返回 ok=false&quot;)    &#125;    filePath := getFileResp.Result.FilePath    return filePath, err&#125;


&emsp;定義一些常量，封裝一個 getTgFilePathByFileID 的方法，用於獲取文件鏈接的 filePath，可以看到該方法也就是普通 get 請求並返回結果，然後便可以進行調用。

// 獲取文件路徑sqlFileID := sqlFileMsg.FileIdsqlFilePath, err := getTgFilePathByFileID(sqlFileID)if err != nil &#123;    return ctx.Reply(&quot;獲取文件路徑失敗: &quot; + g.String(err.Error())).Send().Err()&#125;

讀取文件鏈接裡的文本內容// 通過 HTTP GET 讀取在線文件func readFileContent(fileURL string) (string, error) &#123;    resp, err := http.Get(fileURL)    if err != nil &#123;        return &quot;獲取在線文件失敗:&quot;, err    &#125;    defer resp.Body.Close()    content, err := io.ReadAll(resp.Body)    // fmt.Printf(&quot;文件內容如下：\n%s\n&quot;, string(content))    if err != nil &#123;        return &quot;讀取文件內容失敗:&quot;, err    &#125;    return string(content), err&#125;


&emsp;還是一樣的 get 請求，並創建 1 個 io 用於讀取文件內容並返回，封裝成方法後再在主程序中調用。

// 讀取文件內容sqlFileURL := fmt.Sprintf(&quot;%s/%s&quot;, fileBase, sqlFilePath)sqlString, err := readFileContent(sqlFileURL)if err != nil &#123;    return ctx.Reply(&quot;讀取 SQL 文本失敗: &quot; + g.String(err.Error())).Send().Err()&#125;

sql 簡單校驗// 檢查危險 SQL 操作func isDangerousSQL(sqlText string) (bool, string) &#123;    sql := strings.TrimSpace(strings.ToLower(sqlText))    // DELETE    if regexp.MustCompile(deletePattern).MatchString(sql) &#123;        return true, &quot;DELETE 禁止&quot;    &#125;    // UPDATE 無 WHERE    if strings.HasPrefix(sql, &quot;update&quot;) &amp;&amp; !strings.Contains(sql, &quot; where &quot;) &#123;        return true, &quot;UPDATE 沒有 WHERE 條件&quot;    &#125;    // TRUNCATE    if regexp.MustCompile(truncatePattern).MatchString(sql) &#123;        return true, &quot;TRUNCATE 禁止&quot;    &#125;    // DROP    if regexp.MustCompile(dropPattern).MatchString(sql) &#123;        return true, &quot;DROP 禁止&quot;    &#125;    return false, &quot;&quot;&#125;


&emsp;這一部分的邏輯代碼是同事給我的，也算不得是 sql 檢驗，只是判斷是否是不允許執行的類型 sql，我直接在主程序裡調用：

// 簡單校驗 SQL 文本if checkResult, checkInfo := isDangerousSQL(sqlString); checkResult &#123;    return ctx.Reply(&quot;⚠️ 拒絕執行危險 SQL：檢測到 &quot; + g.String(checkInfo) + &quot; 操作！&quot;).Send().Err()&#125;

數據庫執行// 連接數據庫db, err := gorm.Open(mysql.Open(mysqlConn), &amp;gorm.Config&#123;&#125;)if err != nil &#123;    return ctx.Reply(&quot;⚠️ 數據庫連接失敗，原因是：&quot; + g.String(err.Error())).Send().Err()&#125;// 執行 sqlstart := time.Now()if err := db.Exec(sqlString).Error; err != nil &#123;    eR.Status = &quot;❌ 執行失敗&quot;    eR.SuccessCount = 0    eR.ErrorCount = 1    eR.Msg = &quot;執行 SQL 失敗! &quot; + err.Error()&#125;


&emsp;go 連接數據庫，自然要用到 gorm 這個包。

回覆輸出消息type ExcuteResult struct &#123;    Status       string  `json:&quot;status&quot;`    SiteKey      string  `json:&quot;site_key&quot;`    SuccessCount int     `json:&quot;success_count&quot;`    ErrorCount   int     `json:&quot;error_count&quot;`    Spend        float64 `json:&quot;duration&quot;`    SQL          string  `json:&quot;sql&quot;`    Msg          string  `json:&quot;msg&quot;`&#125;


&emsp;為了避免最後回覆消息所用的變量太多而看不清，在開始時候我定義了一個結構體用於存放相關字段，在適當的時機給其賦值，來完成回覆消息的字符串拼接，最後調用包本身提供的 return ctx.Reply(g.String(resultString)).Send().Err() 方法完。

eR := ExcuteResult&#123;Status: &quot;✅ 更新成功&quot;, SiteKey: &quot;A8&quot;, SuccessCount: 1, ErrorCount: 0, Msg: &quot;OK&quot;&#125;if len(sqlString) &gt; sqlLen &#123;    eR.SQL = sqlString[:sqlLen] + &quot;...(已截斷)&quot;&#125;eR.Spend = time.Since(start).Seconds()// 拼接回復消息resultString := fmt.Sprintf(    &quot;%s\n&quot;+        &quot;執行站點： %s\n\n&quot;+        &quot;已處理的查詢： 1\n&quot;+        &quot;成功： %d\n&quot;+        &quot;錯誤： %d\n&quot;+        &quot;運行時間： %.3fs\n\n&quot;+        &quot;查詢：\n%s\n\n&quot;+        &quot;消息：\n%s\n&quot;,    eR.Status, eR.SiteKey, eR.SuccessCount, eR.ErrorCount, eR.Spend, eR.SQL, eR.Msg,)return ctx.Reply(g.String(resultString)).Send().Err()

Python 版
&emsp;由於我剛來，暫時還是以熟悉各個環境為主，真正需要工作的地方不多，所以時間比較充裕。聊了一下發現坐我左邊的同事使用的是 python，我也想順便複習一下 python，就又冩了一遍代碼。這次選擇 python-telegram-bot（PTB）——這絕對是我在網上找資料時看到最多使用的庫。既然之前的邏輯梳理查不多，這裡就直接上代碼：

#!/usr/bin/env python3import reimport requestsimport aiomysqlimport sqlparsefrom telegram import Updatefrom telegram.ext import Application, MessageHandler, filters, ContextTypesfrom pymysql.constants import CLIENTBOT_TOKEN = &quot;8107087130:AAGOlJ5KgajZU7KFPNdk76yhDn1FZdZCyA8&quot;ADMIN_IDS = [8156491190]SQL_LIMIT_LEN = 500DB_CONFIG = &#123;    &quot;host&quot;: &quot;localhost&quot;,    &quot;user&quot;: &quot;root&quot;,    &quot;password&quot;: &quot;&quot;,    &quot;db&quot;: &quot;demo&quot;,    &quot;charset&quot;: &quot;utf8mb4&quot;,    &quot;autocommit&quot;: True,    &quot;client_flag&quot;: CLIENT.MULTI_STATEMENTS&#125;class SQLExcuteBot:    def __init__(self, bot_token: str, db_config: dict, admin_ids:list[int]):        self.token = bot_token        self.db_config = db_config        self.admin_ids = admin_ids        self.pool = None    async def init_db_pool(self):        &quot;&quot;&quot;初始化 aiomysql 連接池，提升效能&quot;&quot;&quot;        if not self.pool:            self.pool = await aiomysql.create_pool(**self.db_config)            print(&quot;資料庫連接池已建立&quot;)    def is_dangerous_sql(self,sql_text: str) -&gt; tuple[bool, str]:        statements = sqlparse.parse(sql_text)        for statement in statements:            stmt_type = statement.get_type()            if stmt_type in [&quot;DELETE&quot;, &quot;DROP&quot;, &quot;TRUNCATE&quot;]:                return True, f&quot;禁止執行 &#123;stmt_type&#125; 操作&quot;            if stmt_type == &quot;UPDATE&quot;:                has_where = any(                    token.ttype is sqlparse.tokens.Keyword and token.value.upper() == &quot;WHERE&quot;                    for token in statement.tokens                )                if not has_where:                    return True, &quot;UPDATE 指令必須包含 WHERE 條件&quot;        return False, &quot;&quot;    async def execute_sql_safely(self,sql_text: str) -&gt; tuple[bool, str]:        try:            conn = await aiomysql.connect(**DB_CONFIG)            async with conn.cursor() as cur:                await cur.execute(sql_text)                affected_rows = cur.rowcount                count = 0                while True:                    count += cur.rowcount if cur.rowcount &gt; 0 else 0                    if not await cur.nextset():                        break                await conn.ensure_closed()                return True, f&quot;執行成功，影響行數：&#123;affected_rows&#125;&quot;        except Exception as e:            return False, f&quot;資料庫執行報錯: &#123;e&#125;&quot;        finally:            if conn:                conn.close()    async def handle_reply_command(self,update: Update, context: ContextTypes.DEFAULT_TYPE) -&gt; str:        origin_msg = update.message        original_msg_id = origin_msg.message_id        bot_username = (await context.bot.get_me()).username        if f&quot;@&#123;bot_username&#125;&quot; not in origin_msg.text:            return        replied_msg = origin_msg.reply_to_message        if not replied_msg or not replied_msg.document:            await origin_msg.reply_text(&quot;請回復一個 .sql 文件並標記我來執行。&quot;,reply_to_message_id=original_msg_id)            return        try:            file = await replied_msg.document.get_file()        except Exception as e:            await origin_msg.reply_text(&quot;❌ 無法從 Telegram 服務器獲取文件資訊。&quot;,reply_to_message_id=original_msg_id)            return        if not file.file_path.endswith(&quot;sql&quot;):            await origin_msg.reply_text(&quot;❌ SQL 文件必須以 .sql 為後綴名！&quot;,reply_to_message_id=original_msg_id)            return        try:            resp = requests.get(file.file_path,timeout=10)            resp.raise_for_status()        except requests.exceptions.Timeout:            await origin_msg.reply_text(&quot;⏳ 讀取文件超時，請稍後再試。&quot;,reply_to_message_id=original_msg_id)            return        except requests.exceptions.HTTPError as e:            await origin_msg.reply_text(f&quot;❌ 下載失敗，服務器回傳錯誤代碼: &#123;resp.status_code&#125;&quot;,reply_to_message_id=original_msg_id)            return        except Exception as e:            await origin_msg.reply_text(&quot;⚠️ 讀取文件內容時發生非預期錯誤。&quot;,reply_to_message_id=original_msg_id)            return        sql_text = resp.text        is_bad, reason = self.is_dangerous_sql(sql_text)        if is_bad:            await origin_msg.reply_text(f&quot;⚠️ 拒絕執行危險 SQL：檢測到 &#123;reason&#125; 操作！&quot;,reply_to_message_id=original_msg_id)            return        try:            is_bad, reason = self.is_dangerous_sql(sql_text)            if is_bad:                await origin_msg.reply_text(f&quot;🛑 危險操作\n&#123;reason&#125;&quot;,reply_to_message_id=original_msg_id)        except Exception as e:            await origin_msg.reply_text(&quot;⚙️ SQL 引擎檢查失敗，請聯絡開發者。&quot;,reply_to_message_id=original_msg_id)        success, message = await self.execute_sql_safely(sql_text)        if success:            await origin_msg.reply_text(f&quot;✅ &#123;message&#125;&quot;,reply_to_message_id=original_msg_id)        else:            await origin_msg.reply_text(f&quot;❌ &#123;message&#125;&quot;,reply_to_message_id=original_msg_id)    def run(self) -&gt; None:        app = Application.builder().token(self.token).build()        admin_filter = filters.User(user_id=self.admin_ids)        msg_filter= filters.TEXT | filters.Entity(&quot;mention&quot;)        app.add_handler(MessageHandler(admin_filter &amp; msg_filter, self.handle_reply_command))        print(&quot;Bot 啟動中...&quot;)        app.run_polling()if __name__ == &quot;__main__&quot;:    SQLExcuteBot(        bot_token=BOT_TOKEN,        db_config=DB_CONFIG,        admin_ids=ADMIN_IDS    ).run()


&emsp;在自己手搓和 Google AI 的協助下，完成了上面的代碼，不過有以下幾點不同：


之前的 Go 代碼是直接對機器人發送消息的，只要有文件上傳就會執行程序；這次把機器人拉到群組裡，只有在發送文件後並@機器人才會執行程序，這樣也比較合理，能夠更精確地定位信息；
PTB 裡已經封裝 get_file() 的方法，大大簡化 Go 裡獲取通過 fileID 獲取文件的步驟（畢竟 python 的優點之一就是封裝很多實用的方法，輪子夠多）；
sql 的校驗進行優化，如果文件裡包含多個語句，現在也能執行；
在 AI 的建議下，將整段代碼封裝為 class，方便後續調用和維護；
考慮到代碼實現比較重要，就簡化一些文本輸出樣式；


殊途同歸
&emsp;雖然使用的編程語言不同，但在需求和邏輯的規定下，代碼層面沒有太大的區別，無非是一些 API 或者輪子方法的使用上。而且，瞎說句大實話，現在冩程序都用 AI，又不是十分核心的業務，都是些簡單的工具，想法比代碼重要。在和 AI 的對話中，還能不停發現新的問題或優化點，促使代碼冩得更好。

&emsp;&emsp;自從把機器人上雲以來發現並無什麼嚴重問題，偶爾有沒有觸發或者觸發失敗的 bug，也是因為冩代碼時候考慮不周——畢竟這玩意兒沒人測試，輸入的文本情況也比較複雜，當時很難考慮到所有情況。領導前一段時間也可能比較忙，沒空管這個，現在覺得需要優化一下，問問我有啥想法。
&emsp;&emsp;結合我之前看到的代碼，我覺得主要有 2 點急需調整，也就是我接手代碼時就發現的問題：

機器人需要操作不同服務器的不同項目目錄，之前的代碼都是把映射關係通過 Struct + Map 的方式硬編碼在代碼中，這樣每次添加新的項目都需要修改代碼，非常不方便。
機器人對操作消息的分類方式不夠靈活，比如要操作Jenkins、系統服務、執行SQL等，而且不同操作的參數也不太一樣。分類通過 switch + case 就可以，再配合參數的個數，執行具體的操作。

&emsp;&emsp;當時得到的回覆是他冩這塊代碼的時候屬於趕鴨子上架，而且站點項目不多，就圖一個方便沒考慮這麼多。那我也不好說什麼，畢竟剛進公司，人微言輕，萬一領導冩代碼時候有其他的考量呢？現在既然讓我放開手腳，那我肯定要想這麼提高拓展性，才能做到 **能不動代碼就不動代碼，要動代碼也要少動代碼**。
&emsp;&emsp;我把我的想法和大概的實現方式和領導說了一下，領導覺得可以，於是我就開始著手重構，並且記錄一下整個修改的過程，方便後續回顧和優化。
&emsp;&emsp;相較而言，第一個問題肯定是二者之中更為簡單的，所以先從這裡下手，本文也先只介紹這一部分。整個過程大致分為以下 3 個步驟：
定義配置文件sites.yaml.mysql_info: &amp;mysqlConn  host: 127.0.0.1  port: 3306  user: root  password: 123456.redis_info: &amp;redisConn  host: 127.0.0.1  port: 6379  password:  db: 0sites:  a8:    id: 159    name: a8    group: a    host: gouzi-test-a    view: A8-新時代    mysql:      &lt;&lt;: *mysqlConn      database: a8    redis:      &lt;&lt;: *redisConn      db: 8    dir:      root: /home/wwwroot/a8      前臺API: /a8api.b777.vip      後臺API: /a8adminapi.b777.vip      定時任務: /a8quartz.b777.vip    upload:      mini-app: /a8_miniapp/      big-stage: /a8_dawutai/    tasks:      - &#123; name: a8_api, type: 前臺API &#125;      - &#123; name: a8_adminapi, type: 後臺API &#125;      - &#123; name: a8_h5, type: 前臺H5 &#125;      - &#123; name: a8_h5admin, type: 後臺UI &#125;      - &#123; name: a8_quartz, type: 定時任務 &#125;


&emsp;這裡貼出最基本的內容，可以看出如果有其他站點，或者某一個站點需要改動，直接依葫蘆畫瓢複製修改即可。當然，怎麼設計內容和結構，自然是經過一些思考和權衡的：既要清晰易懂，又要考慮代碼裡的解析和使用。除此之外，像 .mysql_info: &amp;mysqlConn 和 .redis_info: &amp;redisConn 是 YAML 的錨點，實屬學到的新技巧。用於減少重複代碼，只要再文本中引用 &amp;mysqlConn 和 &amp;redisConn 即可，畢竟基本的信息（如地址、端口、用戶名、密碼等）一般都不會變動，每個站點單獨配置自己的數據庫即可。

services.yamlsystemservices:  a:    - &#123; alias: dataSync, name: dataSync, type: systemd &#125;    - &#123; alias: 數據同步, name: dataSync, type: init.d &#125;    - &#123; alias: 任務中心導出, name: CenterTask, type: systemd &#125;    - &#123; alias: AutoCredit, name: AutoCredit, type: init.d &#125;  t:    - &#123; alias: autoRemoveBlacklist, name: autoRemoveBlacklist, type: init.d &#125;    - &#123; alias: consumer_doris, name: consumer_doris, type: systemd &#125;    - &#123; alias: consumer_one_doris, name: consumer_one_doris, type: systemd &#125;    - &#123; alias: canal_order, name: canal_order, type: systemd &#125;    - &#123; alias: thirdConsumers, name: thirdConsumers, type: init.d &#125;


&emsp;sites.yaml 中每個站點包含的信息其實很多，需要花點心思設計；而 services.yaml 就沒個必要，反正就是固定的內容，純屬文本記錄，方便增減。

創建結構體sites.gopackage configimport (	&quot;maps&quot;	&quot;slices&quot;	&quot;strings&quot;)type Site struct &#123;	Alias  string            `mapstructure:&quot;alias&quot; json:&quot;alias&quot; yaml:&quot;alias&quot;`	ID     int               `mapstructure:&quot;id&quot; json:&quot;id&quot; yaml:&quot;id&quot;`	Name   string            `mapstructure:&quot;name&quot; json:&quot;name&quot; yaml:&quot;name&quot;`	Host   string            `mapstructure:&quot;host&quot; json:&quot;host&quot; yaml:&quot;host&quot;`	Group  string            `mapstructure:&quot;group&quot; json:&quot;group&quot; yaml:&quot;group&quot;`	View   string            `mapstructure:&quot;view&quot; json:&quot;view&quot; yaml:&quot;view&quot;`	Mysql  MysqlConn         `mapstructure:&quot;mysql&quot; json:&quot;mysql&quot; yaml:&quot;mysql&quot;`	Redis  RedisConn         `mapstructure:&quot;redis&quot; json:&quot;redis&quot; yaml:&quot;redis&quot;`	Dir    map[string]string `mapstructure:&quot;dir&quot; json:&quot;dir&quot; yaml:&quot;dir&quot;`	Tasks  []Task            `mapstructure:&quot;tasks&quot; json:&quot;tasks&quot; yaml:&quot;tasks&quot;`	Upload map[string]string `mapstructure:&quot;upload&quot; json:&quot;upload&quot; yaml:&quot;upload&quot;`&#125;type MysqlConn struct &#123;	Host     string `mapstructure:&quot;host&quot; yaml:&quot;host&quot; json:&quot;host&quot;`	Port     int    `mapstructure:&quot;port&quot; yaml:&quot;port&quot; json:&quot;port&quot;`	User     string `mapstructure:&quot;user&quot; yaml:&quot;user&quot; json:&quot;user&quot;`	Password string `mapstructure:&quot;password&quot; yaml:&quot;password&quot; json:&quot;password&quot;`	Database string `mapstructure:&quot;database&quot; yaml:&quot;database&quot; json:&quot;database&quot;`&#125;type RedisConn struct &#123;	Host     string `mapstructure:&quot;host&quot; yaml:&quot;host&quot; json:&quot;host&quot;`	Port     int    `mapstructure:&quot;port&quot; yaml:&quot;port&quot; json:&quot;port&quot;`	Password string `mapstructure:&quot;password&quot; yaml:&quot;password&quot; json:&quot;password&quot;`	DB       string `mapstructure:&quot;db&quot; yaml:&quot;db&quot; json:&quot;db&quot;`&#125;type Task struct &#123;	Name string `mapstructure:&quot;name&quot; json:&quot;name&quot; yaml:&quot;name&quot;`	Type string `mapstructure:&quot;type&quot; json:&quot;type&quot; yaml:&quot;type&quot;`&#125;// GetUniqueTaskTypes 獲取所有任務類型func (s *Server) GetUniqueTaskTypes() []string &#123;	// 去重過濾器	tempMap := make(map[string]struct&#123;&#125;)	var uniqueTypes []string	for _, site := range s.Sites &#123;		for _, task := range site.Tasks &#123;			if _, exists := tempMap[task.Type]; !exists &#123;				tempMap[task.Type] = struct&#123;&#125;&#123;&#125;				uniqueTypes = append(uniqueTypes, strings.ToLower(task.Type))			&#125;		&#125;	&#125;	return uniqueTypes&#125;func (s *Server) GetAllSiteAlias() []string &#123;	return slices.Sorted(maps.Keys(s.Sites))&#125;


&emsp;代碼本身沒啥好說的，純純通過 Viper 的標籤做字符映射；GetUniqueTaskTypes() 和 GetAllSiteAlias() 兩個方法也僅僅是為了方便後續使用。值得多說一句的是工具的使用：這種標籤映射冩法很死板，但如果定義的結構體字段比較多，哪怕使用快捷鍵 CV 大法，修改也挺麻煩的。好在我用的是 Windsurf——Vscode 的魔改版本，官方宣稱最大的特色可以利用 AI 分析整個項目，然後自動生成代碼。別的地方好不好用我不知道，不過用在這裡確實挺香的，直接讓我少冩了很多重複的代碼，只需要檢查一下標籤和數據結構是否正確，大大提高了開發效率。

service.gopackage configimport (	&quot;strings&quot;)type ServiceItem struct &#123;	Alias string `mapstructure:&quot;alias&quot; json:&quot;alias&quot; yaml:&quot;alias&quot;`	Name  string `mapstructure:&quot;name&quot; json:&quot;name&quot; yaml:&quot;name&quot;`	Type  string `mapstructure:&quot;type&quot; json:&quot;type&quot; yaml:&quot;type&quot;`&#125;// GetServicesBySite 獲取服務組列表func (s *Server) GetServicesBySite(site Site) []ServiceItem &#123;	group := strings.ToLower(strings.TrimSpace(site.Group))	if group != &quot;&quot; &#123;		if svcs, ok := s.SystemServices[group]; ok &#123;			return svcs		&#125;	&#125;	return nil&#125;// GetSvcByName 通過服務名稱獲取該站點的具體服務func (s *Server) GetSvcByName(svcs []ServiceItem, svcName string) *ServiceItem &#123;	for _, svc := range svcs &#123;		if strings.EqualFold(svc.Name, svcName) || strings.EqualFold(svc.Alias, svcName) &#123;			return &amp;svc		&#125;	&#125;	return nil&#125;


&emsp;此處同理，不過 services 簡單，仿照 sites 裡冩 2 個方法用於後續邏輯代碼使用。

config.go// 這邊為了清楚，只顯示添加的字段type Server struct &#123;	Sites map[string]Site `mapstructure:&quot;sites&quot; json:&quot;sites&quot; yaml:&quot;sites&quot;`	SystemServices map[string][]ServiceItem `mapstructure:&quot;systemservices&quot; json:&quot;systemservices&quot; yaml:&quot;systemservices&quot;`&#125;


&emsp;最後在 config.go 裡把剛才定義的加上，注意這裡定義的是 Map 類型，Sites 的 key 是 a8/a1 這種，SystemServices 的 key 是 a/t 這種。其實 SystemServices 不用 Map 也行，不過 Sites 最好用，畢竟站點後續可能會加很多，用 Map 查找的話會比遍歷數組更快。這也就是我在 sites.yaml 裡定義站點時，並沒有用 - 增加多個站點信息的原因。

解析並熱加載viper.gofunc Viper(path ...string) *viper.Viper &#123;	// 省略原來正常的讀取配置文件邏輯 .......	baseDir := filepath.Dir(configPath)	configFiles := []string&#123;config, &quot;services.yaml&quot;, &quot;sites.yaml&quot;&#125;	// 首次加載所有配置	v := ReloadAllConfig(baseDir, configFiles)	// 監聽配置文件變動	v = StartWatchEngine(v, baseDir, configFiles)	global.GVA_CONFIG.AutoCode.Root, _ = filepath.Abs(&quot;..&quot;)	return v&#125;


&emsp;原來的程序我儘量不改動，只是定義了數組，將單一配置文件讀取改為多個配置文件讀取（我也有想過不是手動定義數組，而是通過查找指定目錄下所有 yaml 文件，後來覺得也沒啥必要，畢竟配置文件就那幾個，手動定義更直觀且不容易出錯），並且把讀取解析和監控熱加載都抽取成函數，這樣邏輯上比較清晰。

func ReloadAllConfig(baseDir string, configFiles []string) *viper.Viper &#123;	v := viper.New()	for i, f := range configFiles &#123;		fullPath := filepath.Join(baseDir, f)		v.SetConfigFile(fullPath)		// 主配置		if i == 0 &#123;			if err := v.ReadInConfig(); err != nil &#123;				global.GVA_LOG.Error(fmt.Sprintf(&quot;添加主配置失敗: %v\n&quot;, err))			&#125;		// 附加配置		&#125; else &#123;			if err := v.MergeInConfig(); err != nil &#123;				global.GVA_LOG.Error(fmt.Sprintf(&quot;合併配置失敗, %s 不存在）: %v\n&quot;, f, err))			&#125;		&#125;	&#125;	// viper 解析	var tempConfig cfg.Server	if err := v.Unmarshal(&amp;tempConfig); err != nil &#123;		global.GVA_LOG.Error(fmt.Sprintf(&quot;解析配置失敗: %v\n&quot;, err))		return nil	&#125;	// 全局鎖，安全更新配置	global.GVA_LOCK.Lock()	global.GVA_CONFIG = tempConfig	global.GVA_LOCK.Unlock()	return v&#125;


&emsp;讀取多個配置文件和單個配置文件邏輯基本一致，不過需要 MergeInConfig() 來實現合併。最後的全局鎖，用於安全更新配置，避免併發訪問導致數據不一致。當然，加了之後項目中其他地方讀取 global.GVA_CONFIG 時也需要加鎖。

// ConfigWatchertype ConfigWatcher struct &#123;	baseDir     string	configSet   map[string]struct&#123;&#125;	configFiles []string	mu          sync.Mutex	timer       *time.Timer&#125;// StartWatchEngine 啟動異步監聽引擎func StartWatchEngine(v *viper.Viper, baseDir string, configFiles []string) *viper.Viper &#123;	// Slice 轉 Set 提高效能	configSet := make(map[string]struct&#123;&#125;)	for _, f := range configFiles &#123;		configSet[f] = struct&#123;&#125;&#123;&#125;	&#125;	cw := &amp;ConfigWatcher&#123;		baseDir:     baseDir,		configSet:   configSet,		configFiles: configFiles,	&#125;	// 自定義監聽器	watcher, err := fsnotify.NewWatcher()	if err != nil &#123;		global.GVA_LOG.Error(fmt.Sprintf(&quot;[Watcher] 監聽器初始化失敗: %v\n&quot;, err))		return nil	&#125;	// 後臺 Goroutine 監聽	go func() &#123;		defer watcher.Close()		for &#123;			select &#123;			case event, ok := &lt;-watcher.Events:				if !ok &#123;					return				&#125;				// 過濾事件：冩入、創建、重命名				if event.Op&amp;(fsnotify.Write|fsnotify.Create|fsnotify.Rename) != 0 &#123;					filename := filepath.Base(event.Name)					// 過濾編輯時候的臨時隱藏文件					if isTempFile(filename) &#123;						continue					&#125;					if _, ok := cw.configSet[filename]; ok &#123;						cw.triggerDebounceReload(watcher, event)					&#125;				&#125;			case err, ok := &lt;-watcher.Errors:				if !ok &#123;					return				&#125;				global.GVA_LOG.Error(fmt.Sprintf(&quot;[Watcher] 監聽配置文件異常: %v\n&quot;, err))			&#125;		&#125;	&#125;()	// 監聽目錄	if err := watcher.Add(baseDir); err != nil &#123;		global.GVA_LOG.Error(fmt.Sprintf(&quot;[Watcher] 無法監聽當前 %s 目錄: %v\n&quot;, baseDir, err))	&#125;	return v&#125;func (cw *ConfigWatcher) triggerDebounceReload(watcher *fsnotify.Watcher, event fsnotify.Event) &#123;	// 防抖加鎖倒計時	cw.mu.Lock()	defer cw.mu.Unlock()	if cw.timer != nil &#123;		cw.timer.Stop()	&#125;	// 針對重命名的 Inode	if event.Op&amp;fsnotify.Rename != 0 &#123;		_ = watcher.Remove(event.Name)		_ = watcher.Add(cw.baseDir)	&#125;	cw.timer = time.AfterFunc(200*time.Millisecond, func() &#123;		global.GVA_LOG.Info(fmt.Sprintf(&quot;[Config] 📝 配置文件已變更: %s\n&quot;, event.Name))		ReloadAllConfig(cw.baseDir, cw.configFiles)	&#125;)&#125;func isTempFile(filename string) bool &#123;	return strings.HasPrefix(filename, &quot;.&quot;) ||		strings.HasSuffix(filename, &quot;~&quot;) ||		strings.HasSuffix(filename, &quot;.tmp&quot;)&#125;


&emsp;這裡就是監聽配置文件變動的邏輯，當配置文件變動時，會觸發 ReloadAllConfig() 函數重新加載配置文件。其中防抖機制是為了避免頻繁觸發 reload（比如 vim 修改文件），導致性能問題。同時，針對重命名的 Inode也做了處理，避免監聽失效。


總結&emsp;&emsp;綜上，這一部分的優化到此就算結束了。當然，實際冩代碼的時候並沒有這麼順利，比如剛開始只監聽了一個配置文件，又或者監聽成功了，實際運行的數據並沒有更新……值得一提的是，這次大部分的代碼都是在谷歌瀏覽器的 AI 搜索聊天完成，我闡述需求、想法和問題，它不斷地改進、調整和優化。不敢說現在的代碼就是完美的，但至少程序運行一段時間之後，沒有出現任何問題。而且經過這次重構之後，無論是維護還是修改數據，確實方便很多。由此可見，AI 輔助編程確實能大大提高開發的效率和準確率。
